static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;
  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	tmp[i] = tmp[i] + A[i][j] * x[j];
      for (j = 0; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * tmp[i];
    }
#pragma endscop

  // Optimized code using RISC-V Vector intrinsics
  __rvv_uint8m1_t vx, vy, vtmp;
  __rvv_uint8m1_t vzero = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    {
      vx = __riscv_vle8_v_i8m1(x, i, _PB_N);
      vy = __riscv_vle8_v_i8m1(y, i, _PB_N);
      vtmp = __riscv_vle8_v_i8m1(tmp, i, _PB_M);

      vtmp = __riscv_vfma_vv_i8m1(vtmp, vx, vzero, _PB_N);
      vy = __riscv_vfma_vv_i8m1(vy, vtmp, vzero, _PB_N);

      __riscv_vse8_v_i8m1(y, i, _PB_N, vy);
    }
}

