static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#pragma endscop

  // Optimized code using RISC-V Vector intrinsics
  __riscv_vint8m1_t s_vec = __riscv_vint8m1_t();
  __riscv_vint8m1_t q_vec = __riscv_vint8m1_t();
  __riscv_vint8m1_t r_vec = __riscv_vint8m1_t();
  __riscv_vint8m1_t p_vec = __riscv_vint8m1_t();

  for (i = 0; i < _PB_M; i++)
    s_vec = __riscv_vadd_vv_i8m1(s_vec, __riscv_vint8m1_t(s[i]), 0);
  for (i = 0; i < _PB_N; i++)
    {
      q_vec = __riscv_vadd_vv_i8m1(q_vec, __riscv_vint8m1_t(q[i]), 0);
      for (j = 0; j < _PB_M; j++)
	{
	  s_vec = __riscv_vadd_vv_i8m1(s_vec, __riscv_vint8m1_t(s[j]), 0);
	  q_vec = __riscv_vadd_vv_i8m1(q_vec, __riscv_vint8m1_t(q[i]), 0);
	}
    }

  // Store the results
  for (i = 0; i < _PB_M; i++)
    s[i] = __riscv_vint8m1_t(s_vec);
  for (i = 0; i < _PB_N; i++)
    q[i] = __riscv_vint8m1_t(q_vec);

}

