static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	for (j = 0; j < _PB_N; j++)
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
    }
#pragma endscop

  // RISC-V Vector Optimization
  __riscv_vtype_v2i32_t v_path[N][N];
  __riscv_vtype_v2i32_t v_path_k[N][N];
  __riscv_vtype_v2i32_t v_path_j[N][N];
  __riscv_vtype_v2i32_t v_path_i[N][N];

  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
	  v_path_i = __riscv_vload_v2i32(path[i], N);
	  v_path_k = __riscv_vload_v2i32(path[k], N);
	  v_path_j = __riscv_vload_v2i32(path[j], N);
	  v_path = __riscv_vadd_v2i32(v_path_i, v_path_k);
	  v_path = __riscv_vadd_v2i32(v_path, v_path_j);
	  __riscv_vstore_v2i32(v_path, path[i], N);
	}
    }
}

