static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      C[i][j] *= beta;
      for (k = 0; k < _PB_NK; k++) {
        C[i][j] += alpha * A[i][k] * B[k][j];
      }
    }
  }
#pragma endscop

  // Optimized code using RISC-V Vector intrinsics
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      C[i][j] *= beta;
      for (k = 0; k < _PB_NK; k++) {
        C[i][j] += alpha * A[i][k] * B[k][j];
      }
    }
  }

  // Optimized code using RISC-V Vector assembly
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      C[i][j] *= beta;
      for (k = 0; k < _PB_NK; k++) {
        asm volatile("vsetvli x0, %0, e32, m1" :: "r"(k));
        asm volatile("vle.v v1, (%0)" :: "r"(A[i][k]));
        asm volatile("vle.v v2, (%0)" :: "r"(B[k][j]));
        asm volatile("vmul.vx v3, v1, v2");
        asm volatile("vadd.vx v4, v3, v4");
        asm volatile("vse.v v4, (%0)" :: "r"(C[i][j]));
      }
    }
  }
}

