static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  // Vectorize the first loop
  for (i = 0; i < _PB_N; i += 4)
  {
    __riscv_v4si u1_vec = __riscv_v4si_loadu(u1 + i);
    __riscv_v4si v1_vec = __riscv_v4si_loadu(v1 + i);
    __riscv_v4si u2_vec = __riscv_v4si_loadu(u2 + i);
    __riscv_v4si v2_vec = __riscv_v4si_loadu(v2 + i);

    for (j = 0; j < _PB_N; j += 4)
    {
      __riscv_v4si A_vec = __riscv_v4si_loadu(A + i * _PB_N + j);
      __riscv_v4si A_vec_new = __riscv_v4si_add(A_vec, __riscv_v4si_mul(u1_vec, v1_vec));
      __riscv_v4si A_vec_new = __riscv_v4si_add(A_vec_new, __riscv_v4si_mul(u2_vec, v2_vec));
      __riscv_v4si_storeu(A + i * _PB_N + j, A_vec_new);
    }
  }

  // Vectorize the second loop
  for (i = 0; i < _PB_N; i += 4)
  {
    __riscv_v4si x_vec = __riscv_v4si_loadu(x + i);
    __riscv_v4si y_vec = __riscv_v4si_loadu(y + i);

    for (j = 0; j < _PB_N; j += 4)
    {
      __riscv_v4si A_vec = __riscv_v4si_loadu(A + j * _PB_N + i);
      __riscv_v4si x_vec_new = __riscv_v4si_add(x_vec, __riscv_v4si_mul(beta, A_vec, y_vec));
      __riscv_v4si_storeu(x + i, x_vec_new);
    }
  }

  // Vectorize the third loop
  for (i = 0; i < _PB_N; i += 4)
  {
    __riscv_v4si x_vec = __riscv_v4si_loadu(x + i);
    __riscv_v4si z_vec = __riscv_v4si_loadu(z + i);

    for (j = 0; j < _PB_N; j += 4)
    {
      __riscv_v4si x_vec_new = __riscv_v4si_add(x_vec, z_vec);
      __riscv_v4si_storeu(x + i, x_vec_new);
    }
  }

  // Vectorize the fourth loop
  for (i = 0; i < _PB_N; i += 4)
  {
    __riscv_v4si w_vec = __riscv_v4si_loadu(w + i);
    __riscv_v4si x_vec = __riscv_v4si_loadu(x + i);

    for (j = 0; j < _PB_N; j += 4)
    {
      __riscv_v4si A_vec = __riscv_v4si_loadu(A + i * _PB_N + j);
      __riscv_v4si w_vec_new = __riscv_v4si_add(w_vec, __riscv_v4si_mul(alpha, A_vec, x_vec));
      __riscv_v4si_storeu(w + i, w_vec_new);
    }
  }

#pragma endscop
}

