static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	{
	  tmp[i] = A[i][j] * x[j] + tmp[i];
	  y[i] = B[i][j] * x[j] + y[i];
	}
      y[i] = alpha * tmp[i] + beta * y[i];
    }
#pragma endscop

  // Optimized with RISC-V Vector techniques
  __rvv_uint8m1_t vtmp, vx, vy;
  __rvv_uint8m1_t valpha = __rvv_uint8m1_t(alpha);
  __rvv_uint8m1_t vbeta = __rvv_uint8m1_t(beta);

  for (i = 0; i < _PB_N; i += 8)
    {
      vtmp = __rvv_uint8m1_t(tmp[i]);
      vy = __rvv_uint8m1_t(y[i]);
      for (j = 0; j < _PB_N; j += 8)
	{
	  vx = __rvv_uint8m1_t(x[j]);
	  vtmp = __rvv_uint8m1_t(A[i][j]) * vx + vtmp;
	  vy = __rvv_uint8m1_t(B[i][j]) * vx + vy;
	}
      vtmp = valpha * vtmp + vbeta * vy;
      __rvv_uint8m1_t(tmp[i]) = vtmp;
      __rvv_uint8m1_t(y[i]) = vy;
    }
}

#include <riscv_vector.h>

static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
      R[k][k] = SQRT_FUN(nrm);
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);
	  for (i = 0; i < _PB_M; i++)
	    R[k][j] += Q[i][k] * A[i][j];
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
	}
    }
#pragma endscop

}

